def reward_complete_thinking_structure(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']

        has_thinking = re.search(r'<thinking>.*?</thinking>', response, re.DOTALL) is not None
        has_solution = re.search(r'<solution>.*?</solution>', response, re.DOTALL) is not None

        if has_thinking and has_solution:
            # Check if thinking is not empty
            m_think = re.search(r'<thinking>(.*?)</thinking>', response, re.DOTALL)
            if m_think and len(m_think.group(1).strip()) > 50:
                scores.append(1.0)
            else:
                scores.append(0.0)
        elif has_solution:
            scores.append(0.5)
        else:
            scores.append(-1.0)
    return scores

def penalize_early_truncation(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']

        # If the response is very short and doesn't end with a solution tag, it's likely truncated
        if len(response) < 100:
            if not re.search(r'</solution>\s*$', response):
                scores.append(-1.5)
            else:
                scores.append(0.0)
        else:
            # If it's long but missing the closing solution tag, it might be truncated mid-sentence
            if not re.search(r'</solution>', response):
                # Check if it looks like it's still in thinking
                if re.search(r'<thinking>.*$', response, re.DOTALL):
                    scores.append(-0.5)
                else:
                    scores.append(0.0)
            else:
                scores.append(0.0)
    return scores

def penalize_obvious_arithmetic_errors(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']
        sol = extract_solution(response)
        if sol is None:
            scores.append(0.0)
            continue

        if is_correct(sol, true_answer):
            scores.append(0.0)
            continue

        # If incorrect, check if the error is a simple off-by-one or factor error
        try:
            gt_val = float(true_answer.replace(',', '').replace(' ', ''))
            pred_val = float(sol.replace(',', '').replace(' ', ''))

            # Check for common simple errors
            # 1. Off by 1
            if abs(gt_val - pred_val) == 1:
                scores.append(-0.5)
            # 2. Factor of 2 error (common in geometry/probability)
            elif abs(gt_val - pred_val) == abs(gt_val / 2 - pred_val) and gt_val != 0:
                scores.append(-0.5)
            # 3. Factor of 10 error
            elif abs(gt_val - pred_val) == abs(gt_val * 10 - pred_val) and gt_val != 0:
                scores.append(-0.5)
            else:
                scores.append(0.0)
        except:
            scores.append(0.0)
    return scores

def reward_step_by_step_verification(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']
        think = extract_thinking(response)
        if think is None:
            scores.append(-1.0)
            continue

        # Look for verification phrases
        verification_keywords = ['check', 'verify', 'therefore', 'thus', 'hence', 'so,', 'so ', 'conclude', 'answer is']
        count = 0
        for kw in verification_keywords:
            count += len(re.findall(kw, think, re.IGNORECASE))

        if count >= 2:
            scores.append(1.0)
        elif count == 1:
            scores.append(0.5)
        else:
            scores.append(0.0)
    return scores

def penalize_missing_units_or_context(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']
        sol = extract_solution(response)
        if sol is None:
            scores.append(0.0)
            continue

        # If the ground truth is a number, and the solution is just a number without any context in the solution tag
        # This is a weak signal, but ensures the model doesn't just dump a number.
        if re.match(r'^\d+$', sol.strip()):
            # Check if the solution tag has more than just the number
            m = re.search(r'<solution>(.*?)</solution>', response, re.DOTALL)
            if m:
                content = m.group(1).strip()
                if content == sol.strip():
                    scores.append(-0.2)
                else:
                    scores.append(0.0)
            else:
                scores.append(0.0)
        else:
            scores.append(0.0)
    return scores

def reward_correct_intermediate_steps(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']
        think = extract_thinking(response)
        if think is None:
            scores.append(-1.0)
            continue

        # Heuristic: Check if the thinking contains equations or logical steps
        # Count number of lines with '=' or '->' or '=>'
        lines = think.split('\n')
        eq_lines = [line for line in lines if '=' in line or '->' in line or '=>' in line]

        if len(eq_lines) >= 3:
            scores.append(1.0)
        elif len(eq_lines) >= 1:
            scores.append(0.5)
        else:
            scores.append(0.0)
    return scores

def reward_final_answer_clarity(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']
        m = re.search(r'<solution>(.*?)</solution>', response, re.DOTALL)
        if m is None:
            scores.append(-1.0)
            continue

        sol = m.group(1).strip()

        # Reward if the solution is a single clear number or expression
        # Penalize if it's a long paragraph
        if len(sol) > 50:
            scores.append(-0.5)
        elif re.match(r'^[\d\s\+\-\*/\.\^\(\)]+$', sol):
            scores.append(1.0)
        elif re.match(r'^\\frac.*$', sol):
            scores.append(1.0)
        else:
            scores.append(0.5)
    return scores

